INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66322204', 66322204, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL', 'Pengadaan Kebutuhan Pimpinan Berupa Penyediaan Cenderamata Untuk Pimpinan Tinggi Madya Dan Pratama Dalam Kegiatan Menyambut Idul Fitri 1447 H pada Direktorat Jenderal Kekayaan Intelektual - Provinsi DK Jakarta TA 2026', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 198889800, 'February 2026', 'APBN - PNBP (D)', 1, 1, '7 Hari', 'Dalam rangka menyambut Hari Raya Idul Fitri 1447 H Tahun 2026, sebagai momentum mempererat silaturahmi, meningkatkan kebersamaan, serta memperkuat hubungan kelembagaan antara pimpinan dan pemangku kepentingan, diperlukan penyediaan cenderamata bagi Pimpinan Tinggi Madya dan Pratama. Penyediaan cenderamata ini merupakan bagian dari dukungan kegiatan keprotokolan dan representasi institusi yang bertujuan menjaga citra, etika kelembagaan, serta mempererat hubungan kerja sama antarunit dan mitra strategis. Sehubungan dengan hal tersebut, diperlukan pengadaan kebutuhan pimpinan berupa penyediaan cenderamata untuk Pimpinan Tinggi Madya dan Pratama dalam kegiatan menyambut Idul Fitri 1447 H Tahun Anggaran 2026', '1 Desain Kartu Ucapan 1 Lot 2 Cetak Kartu Ucapan 60 Unit 3 Pembuatan Kemasan Kartu ucapan Menteri dan Wakil Menteri: 2 Unit - Eid Exclusive Mosque Hardbox - 5 Jar Cookies - 1 Set Flower Teacup, Saucer Plate, Fork and Spoon. - Hiasan Box - Twinings Tea Bag - Lindt Chocolate - Paper Belt 4 Pembuatan Kemasan Kartu Ucapan Pimti Madya : 58 Unit - Eid Drawer Hardbox - 5 Jar Cookies - Eid Ramadhan Lantern Light - Hiasan Box - Paper Belt 5 Finishing dan pengepakan 60 Unit', 198889800, 'absurd', 'Pengadaan cenderamata lebaran untuk pimpinan dengan isi hampers premium, perlengkapan minum, teh impor, dan cokelat premium merupakan belanja representasi yang tidak esensial terhadap tugas pokok layanan publik. Sifatnya seremonial, berpotensi memicu kecemburuan sosial, dan seluruh nilainya layak dicermati sebagai pemborosan anggaran.', NULL, NULL, 4, 1, 1, 1, 1, 2663563);
