INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66286114', 66286114, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'Direktorat Jenderal Infrastruktur Digital', 'Pemeliharaan dan Optimalisasi Aplikasi Dashboard Pusat Monitoring Telekomuniaksi Tahun 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 1800000000, 'March 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'a. Pemeliharaan dan Optimalisasi API Operator Seluler dan Dukungan atas temuan (Findings) yang termasuk didalamnya terkait pemeliharaan, penyesuaian, dan pemeliharaan integrasi dan pengolahan data temuan laporan dari operator seluler dan operator PMT serta mengintegrasikan kedalam sistem Dashboard Pusat Monitoring Telekomunikasi b. Implikasi Change Request atas Proses Sertifikasi ISO 27001:2022 pada PMT, ruang lingkup pekerjaan ini yaitu menindaklanjuti kebutuhan perubahan sistem PMT agar selaras dengan proses sertifikasi ISO 27001:2022 c. Pemeliharaan Infrastruktur dan Basis Data (Postgre) yaitu melakukan peninjauan arsitektur basis data PostgreSQL, melaksanakan pemeliharaan berkala (termasuk upgrade versi, optimasi konfigurasi, dan penyesuaian skema) tanpa mengganggu operasional, serta meningkatkan kinerja, ketersediaan layanan, dan mekanisme pemulihan sistem melalui penerapan dan pengujian prosedur backup–restore dan disaster recovery. d. Dukungan teknis untuk pengelolaan basis data geografis (GDB) yaitu pekerjaan ini memberikan dukungan teknis dalam pengelolaan basis data geografis (GDB) yang digunakan PMT, meliputi penataan dan pemeliharaan layer geospasial terkait operator dan jaringan, dukungan pembaruan data spasial dari berbagai sumber, serta peningkatan performa query spasial pada modul pemetaan PMT. e. Pemeliharaan dan Pemutakhiran PMT Maps dan Visualisasi Geografis yaitu Kelompok pekerjaan ini berfokus pada pemeliharaan dan peningkatan kemampuan pemetaan serta pelaporan visual PMT, meliputi penyempurnaan infografis dan dashboard laporan, integrasi data geospasial Rupabumi dan data SIMS, pemutakhiran seluruh aset dan identitas operator pada sistem, serta pembaruan data batas desa untuk mendukung analisis cakupan layanan yang lebih detail.', 'Penyediaan jasa dan layanan sesuai uraian pekerjaan terhadap pemeliharaan Sistem dan Dashboard Pusat Monitoring Telekomunikasi', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2663631);
